@app.cell
def _(mo, pd, v9):
    per_year = (
        v9.groupby(["year", "estimate_status"], as_index=False)
        .agg(
            p50=("gfa_m2", lambda x: x.sum() / 1e9),
            p10=("gfa_p10_m2", lambda x: x.sum() / 1e9),
            p90=("gfa_p90_m2", lambda x: x.sum() / 1e9),
        )
        .sort_values("year")
    )
    per_year["status_label"] = per_year["estimate_status"].map({
        "model_backcast": "Backcast (2015–2019)",
        "observed_anchor": "Observed v6 anchor (2020 / 2023)",
        "log_interpolated": "Log interpolation (2021–2022)",
        "nowcast": "v7 rc1 nowcast (2024–2026)",
    })
    year_summary = per_year.groupby("year", as_index=False)[["p10", "p50", "p90"]].sum()

    stat_cards = mo.hstack(
        [
            mo.stat(value="198", label="Jurisdictions", caption="Unified roster"),
            mo.stat(value="2015–2026", label="Temporal span", caption="12 continuous years"),
            mo.stat(value=f"{year_summary.p50.iloc[0]:.1f} bn m²", label="2015 total (P50)", caption="Backcast start"),
            mo.stat(value=f"{year_summary.p50.iloc[-1]:.1f} bn m²", label="2026 total (P50)", caption="Nowcast end"),
            mo.stat(value="+2.4%/yr", label="2015→2026 CAGR", caption="Full-horizon growth"),
        ],
        justify="space-between",
    )
    stat_cards
    return per_year, stat_cards, year_summary


@app.cell
def _(alt, mo, per_year, year_summary):
    domain = [
        "Backcast (2015–2019)",
        "Observed v6 anchor (2020 / 2023)",
        "Log interpolation (2021–2022)",
        "v7 rc1 nowcast (2024–2026)",
    ]
    range_ = ["#818cf8", "#34d399", "#fbbf24", "#f472b6"]

    band = (
        alt.Chart(year_summary)
        .mark_area(opacity=0.18, color="#6366f1")
        .encode(
            x=alt.X("year:O", title="Year"),
            y=alt.Y("p10:Q", title="Global GFA (bn m²)", scale=alt.Scale(domain=[150, 500])),
            y2="p90:Q",
        )
    )

    line = (
        alt.Chart(year_summary)
        .mark_line(point=alt.OverlayMarkDef(filled=True, size=70), color="#4338ca", strokeWidth=3)
        .encode(
            x="year:O",
            y="p50:Q",
            tooltip=[
                alt.Tooltip("year:O", title="Year"),
                alt.Tooltip("p50:Q", format=".2f", title="P50 (bn m²)"),
                alt.Tooltip("p10:Q", format=".2f", title="P10 (bn m²)"),
                alt.Tooltip("p90:Q", format=".2f", title="P90 (bn m²)"),
            ],
        )
    )

    seg_points = (
        alt.Chart(per_year[per_year.year.isin([2015, 2020, 2022, 2023, 2026])])
        .mark_point(size=130, opacity=0.95)
        .encode(
            x="year:O",
            y=alt.Y("p50:Q", aggregate="sum"),
            color=alt.Color("status_label:N", title="Estimate status", sort=domain, scale=alt.Scale(domain=domain, range=range_)),
            tooltip=[alt.Tooltip("status_label:N", title="Segment")],
        )
    )

    chart = (
        (band + line + seg_points)
        .properties(title="v9 Unified Global GFA Trajectory — segment colours show data provenance", width=860, height=380)
        .configure_axis(gridColor="#f1f5f9")
        .configure_view(strokeWidth=0)
    )

    mo.vstack(
        [
            mo.md("### 🌐 Unified 12-Year Trajectory with Provenance Segments"),
            mo.md(
                "*Purple = 2015–2020 backcast · Green dots = observed v6 anchors (2020/2023) · "
                "Amber dot = approved 2021–2022 interpolation · Pink = v7 rc1 nowcast (2024–2026)*"
            ),
            mo.ui.altair_chart(chart),
        ]
    )
    return band, chart, domain, line, range_, seg_points


@app.cell
def _(alt, mo, pd, v9):
    split_year = (
        v9.dropna(subset=["residential_m2"])
        .groupby("year", as_index=False)[["residential_m2", "non_residential_m2"]]
        .sum()
    )
    split_year["residential_bn"] = split_year.residential_m2 / 1e9
    split_year["non_residential_bn"] = split_year.non_residential_m2 / 1e9

    split_long = split_year.melt(
        id_vars="year",
        value_vars=["residential_bn", "non_residential_bn"],
        var_name="sector",
        value_name="gfa_bn",
    )
    split_long["sector"] = split_long.sector.map(
        {"residential_bn": "Residential", "non_residential_bn": "Non-residential"}
    )

    split_chart = (
        alt.Chart(split_long)
        .mark_bar()
        .encode(
            x=alt.X("year:O", title="Year"),
            y=alt.Y("gfa_bn:Q", title="GFA (bn m²)", stack="zero"),
            color=alt.Color(
                "sector:N",
                title="Sector",
                scale=alt.Scale(domain=["Residential", "Non-residential"], range=["#3b82f6", "#f59e0b"]),
            ),
            tooltip=[
                alt.Tooltip("year:O", title="Year"),
                alt.Tooltip("sector:N", title="Sector"),
                alt.Tooltip("gfa_bn:Q", format=".2f", title="GFA (bn m²)"),
            ],
        )
        .properties(title="Residential vs Non-residential Composition (Method C shares)", width=860, height=340)
        .configure_view(strokeWidth=0)
        .configure_axis(gridColor="#f8fafc")
    )

    mo.vstack([mo.md("### 🏢 Residential / Non-residential Decomposition"), mo.ui.altair_chart(split_chart)])
    return split_chart, split_long, split_year


@app.cell
def _(mo, v9):
    countries = sorted(v9.country_id.unique())
    dropdown = mo.ui.dropdown(
        options=countries,
        value="USA" if "USA" in countries else countries[0],
        label="Select jurisdiction (ISO3):",
    )
    return countries, dropdown


@app.cell
def _(alt, dropdown, mo, pd, v9):
    c = v9[v9.country_id == dropdown.value].sort_values("year")

    c_line = (
        alt.Chart(c)
        .mark_line(point=alt.OverlayMarkDef(filled=True, size=70, color="#0ea5e9"), color="#0ea5e9", strokeWidth=3)
        .encode(
            x=alt.X("year:O", title="Year"),
            y=alt.Y("gfa_m2:Q", title="GFA (m²)", scale=alt.Scale(zero=False)),
            tooltip=[
                alt.Tooltip("year:O", title="Year"),
                alt.Tooltip("gfa_m2:Q", format=",.0f", title="P50 (m²)"),
                alt.Tooltip("gfa_p10_m2:Q", format=",.0f", title="P10 (m²)"),
                alt.Tooltip("gfa_p90_m2:Q", format=",.0f", title="P90 (m²)"),
                alt.Tooltip("estimate_status:N", title="Status"),
            ],
        )
    )

    c_band = (
        alt.Chart(c)
        .mark_area(opacity=0.22, color="#38bdf8")
        .encode(x="year:O", y="gfa_p10_m2:Q", y2="gfa_p90_m2:Q")
    )

    c_chart = (
        (c_band + c_line)
        .properties(title=f"Jurisdiction trajectory — {dropdown.value} (2015–2026)", width=860, height=300)
        .configure_view(strokeWidth=0)
        .configure_axis(gridColor="#f8fafc")
    )

    _row = c[c.year == 2026]
    _g15 = float(c[c.year == 2015].gfa_m2.iloc[0])
    _g26 = float(c[c.year == 2026].gfa_m2.iloc[0])
    _cagr = ((_g26 / _g15) ** (1 / 11) - 1) * 100 if _g15 > 0 else float("nan")

    metrics = mo.hstack(
        [
            mo.stat(value=f"{_g15:,.0f} m²", label="2015 GFA (P50)", caption="Backcast start"),
            mo.stat(value=f"{_g26:,.0f} m²", label="2026 GFA (P50)", caption="Nowcast end"),
            mo.stat(value=f"{_cagr:+.2f}%", label="11-yr CAGR", caption="Full-horizon"),
            mo.stat(
                value=f"{float(c[c.year == 2023].residential_m2.iloc[0] / c[c.year == 2023].gfa_m2.iloc[0] * 100):.1f}%",
                label="2023 residential share",
                caption="Method C",
            ),
        ],
        justify="space-between",
    )

    mo.vstack(
        [
            mo.md("### 🔍 Jurisdiction Drilldown (12 years, provenance-labelled)"),
            dropdown,
            mo.ui.altair_chart(c_chart),
            metrics,
        ]
    )
    return c, c_band, c_chart, c_line, metrics


@app.cell
def _(mo, pd, v9):
    _yr = v9.dropna(subset=["residential_m2"]).copy()
    _yr["res_share"] = _yr.residential_m2 / _yr.gfa_m2
    _latest = _yr[_yr.year == 2026].sort_values("res_share", ascending=False)

    browse = mo.ui.table(
        _latest[["country_id", "year", "gfa_m2", "residential_m2", "non_residential_m2", "res_share", "estimate_status"]],
        selection="multi",
        pagination=True,
        page_size=12,
    )

    mo.vstack(
        [
            mo.md("### 🗃️ 2026 Composition Browser (sortable, multi-select)"),
            mo.md("*Sorted by residential share; toggle rows to filter — table selection syncs with any downstream cells.*"),
            browse,
        ]
    )
    return browse, _latest, _yr


